  // ── Audit i18n: formula admin (How it works) ──
  "k = 2/(periudha+1) · EMA_sot = Çmim·k + EMA_dje·(1−k)": "k = 2/(period+1) · EMA_today = Price·k + EMA_yest·(1−k)",
